SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, s.subject_id, s.hadm_id, s.admittime, s.dischtime, s.deathtime, s.admission_type, s.admit_provider_id, s.admission_location, s.discharge_location, s.insurance, s.language, s.marital_status, s.race, s.edregtime, s.edouttime, s.hospital_expire_flag, COUNT(s.subject_id) AS patient_count, percentile_cont(0.25) within GROUP (ORDER BY m.complexity_score) AS q1_complexity_score, percentile_cont(0.75) within GROUP (ORDER BY m.complexity_score) AS q3_complexity_score, AVG(s.los) AS average_los, SUM(CASE WHEN s.deathtime IS NOT NULL THEN 1 ELSE 0 END) AS in_hospital_mortality_count, SUM(CASE WHEN s.dischtime - s.admittime <= 30 THEN 1 ELSE 0 END) AS readmission_count FROM patients p JOIN admissions s ON p.subject_id = s.subject_id JOIN (SELECT subject_id, COUNT(*) AS complexity_score FROM emar GROUP BY subject_id, (stoptime - starttime)) m ON p.subject_id = m.subject_id WHERE p.gender = 'M' AND p.anchor_age = 45 AND p.anchor_year = 2017 AND p.anchor_year_group IN (40, 41, 42, 43, 44, 45) AND s.discharge_location = 'heart failure' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, s.subject_id, s.hadm_id, s.admittime, s.dischtime, s.deathtime, s.admission_type, s.admit_provider_id, s.admission_location, s.discharge_location, s.insurance, s.language, s.marital_status, s.race, s.edregtime, s.edouttime, s.hospital_expire_flag ORDER BY q1_complexity_score NULLS LAST, q3_complexity_score NULLS LAST;